import fitz
doc = fitz.open('paper.pdf')
print(f'PDF has {len(doc)} pages')
# Search for decoding accuracy mentions
for i, page in enumerate(doc):
    text = page.get_text()
    if 'decod' in text.lower() and ('error' in text.lower() or 'accura' in text.lower()):
        print(f'--- Page {i+1} ---')
        for line in text.split('\n'):
            if 'decod' in line.lower() or 'error' in line.lower() or 'accura' in line.lower():
                print(line.strip())
" 2>&1

